<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue';
import {api,post} from '../api';
import {state,action,inform} from '../state';
import {date} from '../format';
import AlgorithmPicker from '../components/AlgorithmPicker.vue';
import AlgorithmResults from '../components/AlgorithmResults.vue';
import type {LabAlgorithm,LabSelection,LabRun,LabTask,HistoryStatus} from '../algorithmLab';
import type {Security} from '../types';
const emit=defineEmits<{open:[string];rules:[]}>();
const tab=ref('选股工作台'),catalog=ref<LabAlgorithm[]>([]),selected=ref<LabSelection[]>([{id:'ma-trend',parameters:{fast:5,slow:20}},{id:'atr-risk',parameters:{period:14,max_pct:5}}]);
const mode=ref('daily'),scope=ref('all'),combination=ref('all'),busy=ref(false),err=ref(''),run=ref<LabRun>(),runs=ref<LabRun[]>([]),coverage=ref<HistoryStatus>();
const tasks=ref<LabTask[]>([]),events=ref<any[]>([]),q=ref(''),searchResults=ref<Security[]>([]),chosen=ref<Security[]>([]),taskName=ref('我的算法监测'),interval=ref(60),autoReview=ref(false),useJev=ref(false),editingId=ref<string>(),modelStatus=ref<any>();
const filterMode=computed(()=>tab.value==='个股分析'?'custom':scope.value);
const dirty=ref(false),paramsOpen=ref(true);
let poll:ReturnType<typeof setInterval>,searchTimer:ReturnType<typeof setTimeout>;let searchVersion=0;
watch([selected,mode,scope,combination,chosen],()=>{dirty.value=!!run.value;},{deep:true});
watch(mode,()=>{selected.value=[];});
watch(tab,()=>{if(tab.value==='持续监测'&&scope.value==='all')scope.value='custom';if(tab.value==='个股分析'&&chosen.value.length>1)chosen.value=chosen.value.slice(0,1);});
watch(q,()=>{clearTimeout(searchTimer);const version=++searchVersion;if(!q.value.trim()){searchResults.value=[];return;}searchTimer=setTimeout(async()=>{try{const r=await api<Security[]>('/securities?q='+encodeURIComponent(q.value));if(version===searchVersion)searchResults.value=r.data.slice(0,8);}catch(e){err.value=String(e);}},250);});
function choose(s:Security){chosen.value=tab.value==='个股分析'?[s]:[...chosen.value.filter(x=>x.id!==s.id),s];q.value='';searchResults.value=[];}
function config(){return {mode:mode.value,scope:filterMode.value,security_ids:chosen.value.map(s=>s.id),selections:selected.value,combination:combination.value};}
async function load(){try{const [a,h,r,t]=await Promise.all([api<LabAlgorithm[]>('/lab/catalog'),api<HistoryStatus>('/history/status'),api<LabRun[]>('/lab/runs'),api<{tasks:LabTask[];events:any[]}>('/lab/tasks')]);catalog.value=a.data;coverage.value=h.data;runs.value=r.data;tasks.value=t.data.tasks;events.value=t.data.events;}catch(e){err.value=String(e);}}
async function calculate(){busy.value=true;err.value='';const snapshot=JSON.stringify(config());try{run.value=(await post<LabRun>('/lab/run',JSON.parse(snapshot))).data;dirty.value=JSON.stringify(config())!==snapshot;paramsOpen.value=dirty.value;await load();}catch(e){err.value=String(e);}finally{busy.value=false;}}
async function saveTask(){if(filterMode.value==='all'){inform('全市场用于手动选股。持续监测请选择自选或指定池。');return;}const result=await action(()=>post('/lab/tasks',{...config(),name:taskName.value,interval_seconds:interval.value,enabled:true,auto_review:autoReview.value,use_jev:useJev.value,id:editingId.value}),'已启用后台监测；首次检查建立基线，新触发才提醒');if(result){editingId.value=undefined;tab.value='持续监测';await load();}}
async function toggleTask(task:LabTask){if(await action(()=>post('/lab/tasks',{...task,enabled:!task.enabled})))await load();}
async function removeTask(task:LabTask){await action(()=>api('/lab/tasks/'+task.id,{method:'DELETE'}));await load();}
async function inspectHistory(id:string){busy.value=true;try{const result=(await api<LabRun>('/lab/runs/'+id)).data;mode.value=result.mode;await nextTick();scope.value=result.scope;selected.value=JSON.parse(JSON.stringify(result.selections));combination.value=result.combination;chosen.value=result.scope==='custom'?result.rows.map(r=>r.security as Security):[];run.value=result;tab.value='选股工作台';await nextTick();dirty.value=false;paramsOpen.value=false;}catch(e){err.value=String(e);}finally{busy.value=false;}}
function prepareMonitor(id:string){const sec=state.securities.find(s=>s.id===id)??run.value?.rows.find(r=>r.security.id===id)?.security;if(sec){chosen.value=[sec as Security];scope.value='custom';paramsOpen.value=true;tab.value='持续监测';inform('确认算法和周期后点击启用监测');}}
async function editTask(t:LabTask){editingId.value=t.id;mode.value=t.mode;await Promise.resolve();scope.value=t.scope;chosen.value=(t.security_ids??[]).map(id=>state.securities.find(s=>s.id===id)??{id,name:id,code:id.split('.').at(-1)}) as Security[];selected.value=JSON.parse(JSON.stringify(t.selections));combination.value=t.combination;taskName.value=t.name;interval.value=t.interval_seconds;autoReview.value=t.auto_review;useJev.value=!!t.use_jev;paramsOpen.value=true;tab.value='持续监测';}
onMounted(async()=>{try{modelStatus.value=(await api('/lab/model-status')).data;}catch{}await load();poll=setInterval(load,10000);});onUnmounted(()=>{clearInterval(poll);clearTimeout(searchTimer);++searchVersion;});
</script>
<template>
<section class="lab-heading"><div><span class="eyebrow">发现 · 算法研究</span><h1>让每个机会，都有计算依据。</h1><p>选择算法发现候选，在个股上核对，再持续追踪条件变化。</p></div><span class="badge">研究版 · 无自动交易</span></section>
<div class="lab-tabs" role="tablist" aria-label="发现工作区"><button v-for="t in ['选股工作台','个股分析','持续监测','运行记录']" :key="t" role="tab" :aria-selected="tab===t" :class="{active:tab===t}" @click="tab=t;paramsOpen=true">{{t}}</button></div>
<div class="lab-data-strip" v-if="coverage"><span><strong>{{coverage.coverage.history_count.toLocaleString()}}</strong> / {{coverage.coverage.catalog_count.toLocaleString()}} 只已有日线</span><span>最近历史 {{coverage.coverage.last_date??'尚未下载'}}</span><span v-if="coverage.coverage.quality_warning_count">{{coverage.coverage.quality_warning_count}} 只存在来源质量诊断</span><span v-if="coverage.status==='RUNNING'">补数中 {{coverage.completed}} / {{coverage.total}}</span><button class="text-button" @click="action(()=>post('/history/start'),'已启动历史补数');load()">补齐历史</button></div>
<p class="tiny muted" v-if="modelStatus">Jev：{{modelStatus.jev.configured?'已配置':'待配置'}} · Agent：{{modelStatus.agent_configured?'已配置':'待配置'}} · 条件命中为研究线索，模型置信程度不代表盈利概率。</p><p v-if="err" class="error-box" role="alert">{{err}}</p>
<template v-if="tab!=='运行记录'">
<section class="lab-config panel"><div class="lab-section-title"><h2>{{tab==='持续监测'?'建立监测任务':'本次计算'}}</h2><button class="text-button" v-if="run" @click="paramsOpen=!paramsOpen">{{paramsOpen?'收拢配置':'展开配置'}}</button></div>
<div v-show="paramsOpen"><div class="lab-config-row"><label>数据周期<select v-model="mode" :disabled="busy"><option value="daily">完成日线</option><option value="intraday">当日分时成交价</option><option value="news">关联公告事件</option></select></label><label v-if="tab!=='个股分析'">股票范围<select v-model="scope" :disabled="busy"><option value="watch">我的自选</option><option value="custom">指定股票池</option><option value="all" v-if="tab==='选股工作台'">全部沪深证券</option><option value="saved">已打开 / 已保存</option></select></label><label>组合方式<select v-model="combination" :disabled="busy"><option value="all">所有算法同时满足</option><option value="any">任一算法满足</option></select></label></div>
<div v-if="filterMode==='custom'" class="lab-stock-picker"><label>{{tab==='个股分析'?'选择分析股票':'添加研究股票'}}<input v-model="q" placeholder="输入代码、名称或拼音" aria-label="搜索研究股票"></label><div class="lab-search-results" v-if="searchResults.length"><button v-for="s in searchResults" :key="s.id" @click="choose(s)">{{s.name}} <span>{{s.code}}</span></button></div><div class="lab-chosen"><button v-for="s in chosen" :key="s.id" @click="chosen=chosen.filter(x=>x.id!==s.id)">{{s.name}} {{s.code}} ×</button></div></div>
<div class="lab-algorithm-title"><strong>选择算法</strong><span class="tiny muted">已选 {{selected.length}} 项 · 参数可展开调整</span></div><AlgorithmPicker :catalog="catalog" v-model="selected" :mode="mode"/>
<div class="lab-task-options" v-if="tab==='持续监测'"><label>任务名称<input v-model="taskName" maxlength="60"></label><label>检查间隔<select v-model="interval"><option :value="30">30 秒</option><option :value="60">60 秒</option><option :value="300">5 分钟</option></select></label><label class="lab-inline-check"><input type="checkbox" v-model="useJev">先由 Jev 判断是否进入复核（需密钥）</label><label class="lab-inline-check"><input type="checkbox" v-model="autoReview">新触发后请求 Agent 复核（需配置，可能计费，每小时≤4次）</label></div></div>
<div class="lab-run-bar"><span class="tiny muted">{{mode==='daily'?'只用已完成日线 · 原价':mode==='intraday'?'真实成交价序列 · 非分钟OHLC':'新公告目录 · 不推导利好利空'}}</span><button class="button" :disabled="busy||!selected.length||(filterMode==='custom'&&!chosen.length)" @click="calculate">{{busy?'正在计算…':'运行一次'}}</button><button v-if="tab==='持续监测'" class="button primary" :disabled="busy||!selected.length||(filterMode==='custom'&&!chosen.length)" @click="saveTask">{{editingId?'保存调整并重建基线':'启用监测'}}</button><button v-if="editingId" class="text-button" @click="editingId=undefined">取消调整</button></div></section>
<section v-if="tab!=='持续监测'" class="lab-result-area"><div class="lab-section-title"><h2>算法结果</h2><span class="badge" v-if="run">{{dirty?'配置已变，请重新运行':'已完成'}}</span></div><AlgorithmResults v-if="run" :run="run" @open="emit('open',$event)" @monitor="prepareMonitor"/><div class="lab-empty" v-else><span class="lab-empty-number">01 → 02 → 03</span><h3>选择条件，运行计算，核对机会。</h3><p>每只股票保留各算法结果与数据日期。历史不足明确跳过，不补造数据。</p><p class="tiny muted">可先用“我的自选”体验，再切换全市场。</p></div></section>
<section v-if="tab==='持续监测'" class="lab-monitor-list"><div class="lab-section-title"><h2>后台任务</h2><span class="tiny muted">服务运行期间执行 · 离开页面仍继续</span></div><div v-if="!tasks.length" class="lab-empty">选择算法与股票范围后，点击“启用监测”。</div><article class="lab-task" v-for="t in tasks" :key="t.id"><div><strong>{{t.name}}</strong><span class="badge" :class="t.enabled?'blue':''">{{t.enabled?'监测中':'已暂停'}}</span><p class="tiny muted">{{t.mode==='daily'?'日线':t.mode==='intraday'?'分时':'公告'}} · {{t.selections.map(s=>catalog.find(a=>a.id===s.id)?.name??s.id).join(' / ')}} · 每 {{t.interval_seconds}} 秒 · {{t.use_jev?'Jev分流':'规则直接提醒'}}</p><p class="tiny">最近检查 {{t.last_checked_at?date(t.last_checked_at):'等待首次基线'}}<span class="error-line" v-if="t.error"> · {{t.error}}</span></p></div><button class="button small" @click="editTask(t)">调整</button><button class="button small" @click="toggleTask(t)">{{t.enabled?'暂停':'恢复'}}</button><button class="text-button" @click="removeTask(t)">删除</button></article><h2 class="lab-event-heading">触发流水</h2><div v-if="!events.length" class="lab-empty">首次检查建立基线，之后的新事件才触发通知。</div><article v-for="e in events" :key="e.id" class="lab-task"><div><strong>{{e.row.security.name}} · {{e.task_name}}</strong><p>{{e.row.action}}</p><span class="tiny muted">{{date(e.created_at)}} · 数据 {{e.row.data_as_of}}</span><p v-if="e.decision">Jev：{{e.decision.summary}}</p><p v-if="e.model_note">{{e.model_note}}</p><p v-if="e.review">Agent：{{e.review.summary}}</p></div><button class="text-button" @click="emit('open',e.row.security.id)">查看个股</button></article></section>
</template>
<section v-else><div v-if="!runs.length" class="lab-empty">完成一次计算后，算法、参数和结果会保存在这里。</div><article v-for="r in runs" :key="r.id" class="lab-task"><div><strong>{{date(r.started_at)}}</strong><p>{{r.selections.map(s=>catalog.find(a=>a.id===s.id)?.name??s.id).join(' / ')}}</p><span class="tiny muted">计算 {{r.total}} 只 · 命中 {{r.matched}} 只 · 数据不足 {{r.skipped}} 只</span></div><button class="button small" @click="inspectHistory(r.id)">查看结果</button></article></section>
<p class="lab-footer-note">可解释研究基线 · 尚未完成样本外收益验证 · 命中数量不等于盈利概率 · 不触发交易</p>
</template>
